import { useQuery } from '@tanstack/react-query';
import { Alert, Card, Space, Table, Tag, Tooltip, Typography } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { PageContainer } from '@/components/PageContainer';
import { apiClient, ApiError } from '@/api/client';
import type {
  AuditEvent,
  AuditEventType,
  AuditOutcome,
  HashChainVerification,
} from '@/types/models';

const { Text } = Typography;

const eventTypeColorMap: Record<AuditEventType, string> = {
  CREATE: 'blue',
  UPDATE: 'cyan',
  DELETE: 'red',
  APPROVE: 'green',
  REJECT: 'orange',
  EXECUTE: 'purple',
  SYSTEM: 'default',
};

const outcomeColorMap: Record<AuditOutcome, string> = {
  SUCCESS: 'success',
  FAILURE: 'error',
  DENIED: 'warning',
};

function truncateHash(hash: string): string {
  return hash.length > 16 ? `${hash.slice(0, 8)}…${hash.slice(-6)}` : hash;
}

function useAuditEvents() {
  return useQuery<AuditEvent[], ApiError>({
    queryKey: ['audit-events'],
    queryFn: () => apiClient.get<AuditEvent[]>('/audit/events'),
  });
}

function useHashChainVerification() {
  return useQuery<HashChainVerification, ApiError>({
    queryKey: ['audit-hash-chain-verification'],
    queryFn: () => apiClient.get<HashChainVerification>('/audit/verify'),
  });
}

const columns: ColumnsType<AuditEvent> = [
  {
    title: '时间戳',
    dataIndex: 'timestamp',
    key: 'timestamp',
    width: 200,
    render: (value: string) => (
      <Text data-testid="audit-row-timestamp">{value}</Text>
    ),
  },
  {
    title: '事件类型',
    dataIndex: 'eventType',
    key: 'eventType',
    width: 120,
    render: (value: AuditEventType) => (
      <Tag color={eventTypeColorMap[value]} data-testid="audit-row-event-type">
        {value}
      </Tag>
    ),
  },
  {
    title: '操作人',
    dataIndex: 'actorId',
    key: 'actorId',
    width: 160,
    render: (value: string) => (
      <span data-testid="audit-row-actor-id">{value}</span>
    ),
  },
  {
    title: '操作',
    dataIndex: 'action',
    key: 'action',
    width: 200,
    render: (value: string) => (
      <span data-testid="audit-row-action">{value}</span>
    ),
  },
  {
    title: '资源类型',
    dataIndex: 'resourceType',
    key: 'resourceType',
    width: 140,
  },
  {
    title: '资源ID',
    dataIndex: 'resourceId',
    key: 'resourceId',
    width: 200,
    render: (value: string) => (
      <Text code data-testid="audit-row-resource-id">{value}</Text>
    ),
  },
  {
    title: '结果',
    dataIndex: 'outcome',
    key: 'outcome',
    width: 100,
    render: (value: AuditOutcome) => (
      <Tag color={outcomeColorMap[value]} data-testid="audit-row-outcome">
        {value}
      </Tag>
    ),
  },
  {
    title: '记录哈希',
    dataIndex: 'recordHash',
    key: 'recordHash',
    width: 200,
    render: (value: string) => (
      <Tooltip title={value} data-testid="audit-row-hash-tooltip">
        <Text code copyable={{ text: value }} data-testid="audit-row-record-hash">
          {truncateHash(value)}
        </Text>
      </Tooltip>
    ),
  },
  {
    title: '前序哈希',
    dataIndex: 'previou
sHash',
    key: 'previousHash',
    width: 180,
    render: (value: string | null) =>
      value ? (
        <Tooltip title={value}>
          <Text code type="secondary" data-testid="audit-row-previous-hash">
            {truncateHash(value)}
          </Text>
        </Tooltip>
      ) : (
        <Text type="secondary">GENESIS</Text>
      ),
  },
  {
    title: '关联ID',
    dataIndex: 'correlationId',
    key: 'correlationId',
    width: 200,
    render: (value: string | null) =>
      value ? (
        <Text code data-testid="audit-row-correlation-id">{value}</Text>
      ) : (
        <Text type="secondary">-</Text>
      ),
  },
];

export function AuditViewer(): JSX.Element {
  const { data, isLoading, isError } = useAuditEvents();
  const { data: verification } = useHashChainVerification();

  const pageState = isLoading ? 'LOADING' : isError ? 'ERROR' : 'READY';

  const chainVerified = verification?.verified ?? false;
  const brokenAt = verification?.brokenAtEventId ?? null;

  return (
    <PageContainer pageId="operations.audit" state={pageState} title="审计追踪">
      <Card style={{ marginBottom: 16 }} data-testid="audit-hash-chain-card">
        <Alert
          type={chainVerified ? 'success' : 'error'}
          showIcon
          message={
            chainVerified
              ? '哈希链验证通过'
              : '哈希链验证失败 — 链条完整性被破坏'
          }
          description={
            <Space direction="vertical">
              <span data-testid="audit-chain-verified">
                验证状态: {chainVerified ? '通过' : '失败'}
              </span>
              <span data-testid="audit-chain-total-events">
                事件总数: {verification?.totalEvents ?? 0}
              </span>
              {verification?.lastVerifiedHash && (
                <span data-testid="audit-chain-last-hash">
                  最后验证哈希:{' '}
                  <Text code>{truncateHash(verification.lastVerifiedHash)}</Text>
                </span>
              )}
              {brokenAt && (
                <span
                  style={{ color: '#cf1322' }}
                  data-testid="audit-chain-broken-at"
                >
                  断裂事件ID: <Text code>{brokenAt}</Text>
                </span>
              )}
            </Space>
          }
          data-testid="audit-chain-alert"
        />
      </Card>

[CmdletBinding()]
param(
  [string]$EnvironmentPath = (Join-Path $PSScriptRoot '..\..\.env'),
  [string]$BaseUrl = 'http://127.0.0.1:13000/fineract-provider'
)

$ErrorActionPreference = 'Stop'
if (-not (Test-Path -LiteralPath $EnvironmentPath)) {
  throw "Local environment file is missing: $EnvironmentPath"
}

$values = @{}
Get-Content -LiteralPath $EnvironmentPath | Where-Object { $_ -match '^[A-Z0-9_]+=' } | ForEach-Object {
  $parts = $_ -split '=', 2
  $values[$parts[0]] = $parts[1]
}
if ($values.ContainsKey('FINERACT_ADMIN_PASSWORD')) {
  throw 'FINERACT_ADMIN_PASSWORD is already present; refusing to rotate the administrator a second time.'
}

$current = [Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes('mifos:password'))
$headers = @{ Authorization = "Basic $current"; 'fineract-platform-tenantid' = 'default'; 'Content-Type' = 'application/json' }
$bytes = [byte[]]::new(32)
[System.Security.Cryptography.RandomNumberGenerator]::Fill($bytes)
$newPassword = 'Ba1!' + [Convert]::ToBase64String($bytes).Replace('+', 'A').Replace('/', 'B').Replace('=', 'C')
$body = @{ password = $newPassword; repeatPassword = $newPassword } | ConvertTo-Json -Compress

Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/users/1/pwd" -Headers $headers -Body $body | Out-Null
[System.IO.File]::AppendAllText((Resolve-Path -LiteralPath $EnvironmentPath), "`nFINERACT_ADMIN_USERNAME=mifos`nFINERACT_ADMIN_PASSWORD=$newPassword`n", (New-Object System.Text.UTF8Encoding($false)))
Write-Output 'Rotated the default Fineract administrator password and stored the replacement only in the local environment file.'

package local.bank.channel.payments;

import java.util.UUID;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InboxService {
  private final JdbcTemplate jdbc;
  public InboxService(JdbcTemplate jdbc) { this.jdbc = jdbc; }
  @Transactional
  public boolean claim(String consumer, UUID eventId) {
    try {
      jdbc.update("INSERT INTO inbox_event(consumer_name,event_id) VALUES (?,?)", consumer, eventId);
      return true;
    } catch (DuplicateKeyException duplicate) {
      return false;
    }
  }
}

package local.bank.channel;

import java.net.URI;
import org.slf4j.MDC;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.client.RestClientResponseException;
import org.springframework.web.server.ResponseStatusException;

@RestControllerAdvice
public class ProblemHandler {
  @ExceptionHandler(RestClientResponseException.class)
  ProblemDetail coreFailure(RestClientResponseException ex) {
    ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.BAD_GATEWAY);
    problem.setType(URI.create("urn:bank:error:adapter-failure"));
    problem.setTitle("Core adapter request failed");
    problem.setProperty("code", "FINERACT_ADAPTER_FAILURE");
    problem.setProperty("coreStatus", ex.getStatusCode().value());
    String requestId = MDC.get("requestId");
    String correlationId = MDC.get("correlationId");
    if (requestId != null) problem.setProperty("requestId", requestId);
    if (correlationId != null) problem.setProperty("correlationId", correlationId);
    String body = ex.getResponseBodyAsString();
    if (body != null && !body.isBlank())
      problem.setProperty("coreResponse", body.substring(0, Math.min(body.length(), 2000)));
    return problem;
  }

@ExceptionHandler(ResponseStatusException.class)
  ProblemDetail statusException(ResponseStatusException ex) {
    ProblemDetail problem = ProblemDetail.forStatus(ex.getStatusCode());
    problem.setTitle(ex.getReason() == null ? "Request error" : ex.getReason());
    problem.setProperty("code", mapStatusCode(ex.getStatusCode().value()));
    String requestId = MDC.get("requestId");
    String correlationId = MDC.get("correlationId");
    if (requestId != null) problem.setProperty("requestId", requestId);
    if (correlationId != null) problem.setProperty("correlationId", correlationId);
    return problem;
  }

  @ExceptionHandler(IllegalArgumentException.class)
  ProblemDetail invalidRequest(IllegalArgumentException ex) {
    ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
    problem.setType(URI.create("urn:bank:error:invalid-request"));
    problem.setTitle("Invalid request");
    problem.setProperty("code", "INVALID_REQUEST");
    problem.setDetail(ex.getMessage());
    String requestId = MDC.get("requestId");
    String correlationId = MDC.get("correlationId");
    if (requestId != null) problem.setProperty("requestId", requestId);
    if (correlationId != null) problem.setProperty("correlationId", correlationId);
    return problem;
  }

  private String mapStatusCode(int status) {
    return switch (status) {
      case 400 -> "BAD_REQUEST";
      case 401 -> "UNAUTHORIZED";
      case 403 -> "FORBIDDEN";
      case 404 -> "NOT_FOUND";
      case 409 -> "CONFLICT";
      case 422 -> "UNPROCESSABLE_ENTITY";
      case 429 -> "RATE_LIMITED";
      default -> "ERROR";
    };
  }
}
